/* ===== 3D — procedural high-fidelity DIGITAL smartwatch, OLED screen renders the live design ===== */
let R3,S3,C3,CTRL3,COMP3,caseMat,SCREEN_U,built3=false;
function init3D(){
  if(built3) return; built3=true;
  const cont=document.getElementById('cv3d'); const w=cont.clientWidth||340,hgt=cont.clientHeight||420; const dpr=Math.min(window.devicePixelRatio||1,2);
