  R3.toneMapping=THREE.ACESFilmicToneMapping; R3.toneMappingExposure=1.1;
  cont.innerHTML=''; cont.appendChild(R3.domElement);
  CTRL3=new OrbitControls(C3,R3.domElement); CTRL3.enableDamping=true; CTRL3.autoRotate=true; CTRL3.autoRotateSpeed=1.1; CTRL3.enablePan=false; CTRL3.minDistance=4; CTRL3.maxDistance=12;
  S3.add(new THREE.AmbientLight(0xffffff,0.35));
