  const g=new THREE.Group();
  caseMat=new THREE.MeshStandardMaterial({color:0x1b1b20,metalness:1.0,roughness:0.28});
  const body=new THREE.Mesh(new RoundedBoxGeometry(2.35,2.85,0.55,8,0.36), caseMat); g.add(body);
  // OLED screen showing the live shader (uShape=1 rounded-rect)
  const su=makeUniforms2(1); su.dpr.value=dpr; SCREEN_U=su;
  const screenMat=new THREE.ShaderMaterial({uniforms:su,vertexShader:VERT,fragmentShader:FRAG2,transparent:true});
  const screen=new THREE.Mesh(new THREE.PlaneGeometry(2.0,2.5), screenMat); screen.position.z=0.285; g.add(screen);
  // subtle glass bezel
  const glass=new THREE.Mesh(new THREE.PlaneGeometry(2.1,2.6), new THREE.MeshPhysicalMaterial({transmission:0.9,transparent:true,opacity:0.14,roughness:0.05,metalness:0,clearcoat:1})); glass.position.z=0.30; g.add(glass);
  // digital crown + side button
  const metal=new THREE.MeshStandardMaterial({color:0x33333a,metalness:1,roughness:0.2});
  const crown=new THREE.Mesh(new THREE.CylinderGeometry(0.13,0.13,0.2,28), metal); crown.rotation.z=Math.PI/2; crown.position.set(1.25,0.4,0); g.add(crown);
  const sbtn=new THREE.Mesh(new THREE.CylinderGeometry(0.06,0.06,0.5,24), metal); sbtn.rotation.z=Math.PI/2; sbtn.position.set(1.22,-0.55,0); g.add(sbtn);
  // bands
  const bandMat=new THREE.MeshStandardMaterial({color:0x0e0e12,metalness:0.15,roughness:0.75});
  const bTop=new THREE.Mesh(new RoundedBoxGeometry(1.9,1.7,0.34,6,0.26), bandMat); bTop.position.set(0,2.1,-0.05); g.add(bTop);
  const bBot=bTop.clone(); bBot.position.set(0,-2.1,-0.05); g.add(bBot);
  S3.add(g);
  COMP3=new EffectComposer(R3); COMP3.setPixelRatio(dpr); COMP3.setSize(w,hgt);
  COMP3.addPass(new RenderPass(S3,C3)); COMP3.addPass(new UnrealBloomPass(new THREE.Vector2(w,hgt),0.75,0.55,0.15)); // bloom = OLED glow
  // HDRI reflections on the metal case
  new RGBELoader().load(CFG.hdrUrl||'./assets/studio.hdr',(tex)=>{ tex.mapping=THREE.EquirectangularReflectionMapping; S3.environment=tex; });
}

