/* ===== v35 LIQUID OLED — raymarched face (ported from REFRACT_APP_v35) ===== */
const LIQ_VERT = `varying vec2 vUv; void main(){ vUv=uv; gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.0); }`;
const LIQ_FRAG = `precision highp float;
uniform float uTime,uMorph,uFlow,uHeat; uniform vec3 c1,c2; varying vec2 vUv;
float sdSphere(vec3 p,float s){return length(p)-s;}
float smin(float a,float b,float k){float h=clamp(0.5+0.5*(b-a)/k,0.0,1.0);return mix(b,a,h)-k*h*(1.0-h);}
float map(vec3 p){
  float t=uTime*(0.5+uFlow*2.0);
  float d1=sdSphere(p,0.8);
  vec3 o1=vec3(sin(t)*1.2,cos(t*1.3)*0.4,cos(t)*1.2);
  float d2=sdSphere(p-o1*uMorph,0.45*uMorph);
  float dist=sin(p.x*5.0+t)*sin(p.y*4.0+t)*sin(p.z*6.0+t)*0.15*uHeat;
  return smin(d1,d2,0.5)+dist;
}
vec3 calcNormal(vec3 p){vec2 h=vec2(0.01,0);return normalize(vec3(map(p+h.xyy)-map(p-h.xyy),map(p+h.yxy)-map(p-h.yxy),map(p+h.yyx)-map(p-h.yyx)));}
void main(){
  vec2 uv=(vUv-0.5)*2.0;
  vec3 ro=vec3(0.0,0.0,2.5); vec3 rd=normalize(vec3(uv,-1.0));
  float t=0.0; float d=0.0;
  for(int i=0;i<40;i++){ vec3 p=ro+rd*t; d=map(p); if(abs(d)<0.01||t>5.0) break; t+=d; }
  vec3 col=vec3(0.02);
  if(t<5.0){
    vec3 p=ro+rd*t; vec3 n=calcNormal(p);
    vec3 ld=normalize(vec3(1.0,1.0,1.0)); vec3 vd=normalize(ro-p);
    float diff=max(dot(n,ld),0.0);
    float fres=pow(1.0-max(dot(n,vd),0.0),3.0);
    vec3 rCol=mix(c1,c2,uHeat);
    col=vec3(0.08)*diff + rCol*fres*(1.0+uHeat*2.0) + c1*diff*0.25;
  }
  gl_FragColor=vec4(col,1.0);
}`;

/* ===== 3D — v17: MASTER product shell + v35 AAA watch / OLED face pipeline ===== */
let R3,S3,C3,CTRL3,COMP3,caseMat,bezelMat,SCREEN_U,SCREEN_MESH,FACE_SPEC,FACE_LIQ,built3=false;
function useLiquidFace(){ return state.category==='Liquid'; }
function syncFaceMaterial(){
  if(!SCREEN_MESH||!FACE_SPEC||!FACE_LIQ) return;
  SCREEN_MESH.material = useLiquidFace() ? FACE_LIQ : FACE_SPEC;
}
function init3D(){
  if(built3) return; built3=true;
  const cont=document.getElementById('cv3d'); const w=cont.clientWidth||340,hgt=cont.clientHeight||420; const dpr=Math.min(window.devicePixelRatio||1,2);
  S3=new THREE.Scene();
  C3=new THREE.PerspectiveCamera(35,w/hgt,0.001,100); C3.position.set(0,0,5.4);
  R3=new THREE.WebGLRenderer({alpha:true,antialias:true}); R3.setPixelRatio(dpr); R3.setSize(w,hgt);
  R3.toneMapping=THREE.ACESFilmicToneMapping; R3.toneMappingExposure=1.15;
  cont.innerHTML=''; cont.appendChild(R3.domElement);
  CTRL3=new OrbitControls(C3,R3.domElement); CTRL3.enableDamping=true; CTRL3.autoRotate=true; CTRL3.autoRotateSpeed=1.0; CTRL3.enablePan=false; CTRL3.enableZoom=true; CTRL3.minDistance=3.2; CTRL3.maxDistance=10;
  S3.add(new THREE.AmbientLight(0xffffff,0.5));
  const key=new THREE.DirectionalLight(0xffffff,2.0); key.position.set(5,5,5); S3.add(key);
  const rim=new THREE.DirectionalLight(0x6b8cff,0.55); rim.position.set(-5,-2,-4); S3.add(rim);

  // --- AAA smartwatch (geometry + materials ported from REFRACT_APP_v35) ---
  const g=new THREE.Group();
  caseMat=new THREE.MeshStandardMaterial({color:0xb8b8c0,metalness:0.9,roughness:0.15,envMapIntensity:1.5});
  const body=new THREE.Mesh(new RoundedBoxGeometry(1.4,1.7,0.3,10,0.25), caseMat); g.add(body);
  bezelMat=new THREE.MeshStandardMaterial({color:0x050505,metalness:1.0,roughness:0.05,envMapIntensity:2.0});
  const bezel=new THREE.Mesh(new RoundedBoxGeometry(1.35,1.65,0.32,10,0.23), bezelMat); g.add(bezel);

  // OLED face: MASTER SPECS/FRAG2 (all designs) + v35 liquid raymarch (Liquid category)
  const su=makeUniforms2(1); su.dpr.value=dpr; SCREEN_U=su;
  FACE_SPEC=new THREE.ShaderMaterial({uniforms:su,vertexShader:VERT,fragmentShader:FRAG2,transparent:true});
  FACE_LIQ=new THREE.ShaderMaterial({
    uniforms:{
      uTime:{value:0}, uMorph:{value:0.5}, uFlow:{value:0.5}, uHeat:{value:0.5},
      c1:{value:new THREE.Color('#6a9cff')}, c2:{value:new THREE.Color('#ff4d8d')}
    },
    vertexShader:LIQ_VERT, fragmentShader:LIQ_FRAG
  });
  SCREEN_MESH=new THREE.Mesh(new RoundedBoxGeometry(1.2,1.5,0.33,10,0.15), FACE_SPEC);
  g.add(SCREEN_MESH);
  syncFaceMaterial();

  // Digital crown
  const crownMat=new THREE.MeshStandardMaterial({color:0x111111,metalness:0.9,roughness:0.2});
  const crown=new THREE.Mesh(new THREE.CylinderGeometry(0.12,0.12,0.1,32), crownMat);
  crown.rotation.z=Math.PI/2; crown.position.set(0.72,0.3,0); g.add(crown);
  // Side button
  const sbtn=new THREE.Mesh(new THREE.CylinderGeometry(0.07,0.07,0.08,28), crownMat);
  sbtn.rotation.z=Math.PI/2; sbtn.position.set(0.72,-0.25,0); g.add(sbtn);
  // Bands (curved back slightly — v35)
  const bandMat=new THREE.MeshStandardMaterial({color:0x0a0a0a,metalness:0.1,roughness:0.9});
  const bandGeo=new THREE.BoxGeometry(0.9,2.5,0.15);
  const bTop=new THREE.Mesh(bandGeo, bandMat); bTop.position.set(0,1.6,-0.05); bTop.rotation.x=-0.2; g.add(bTop);
  const bBot=new THREE.Mesh(bandGeo, bandMat); bBot.position.set(0,-1.6,-0.05); bBot.rotation.x=0.2; g.add(bBot);
  S3.add(g);

  COMP3=new EffectComposer(R3); COMP3.setPixelRatio(dpr); COMP3.setSize(w,hgt);
  COMP3.addPass(new RenderPass(S3,C3));
  COMP3.addPass(new UnrealBloomPass(new THREE.Vector2(w,hgt),0.85,0.55,0.12)); // OLED glow
  new RGBELoader().load(CFG.hdrUrl||'./assets/studio.hdr',(tex)=>{ tex.mapping=THREE.EquirectangularReflectionMapping; S3.environment=tex; });
  applyMaterial();
}

